/* From Uiverse.io by vinodjangid07  - Tags: animation, active, switch, lock, toggle, toggle switch */
.__UIV_SCOPE__ #lock {
  display: none;
}
.__UIV_SCOPE__ .lock-label {
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgb(80, 80, 80);
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .lock-wrapper {
  width: fit-content;
  height: fit-content;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transform: rotate(-10deg);
}
.__UIV_SCOPE__ .shackle {
  background-color: transparent;
  height: 9px;
  width: 14px;
  border-top-right-radius: 10px;
  border-top-left-radius: 10px;
  border-top: 3px solid white;
  border-left: 3px solid white;
  border-right: 3px solid white;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .lock-body {
  width: 15px;
}
.__UIV_SCOPE__ #lock:checked + .lock-label .lock-wrapper .shackle {
  transform: rotateY(150deg) translateX(3px);
  transform-origin: right;
}
.__UIV_SCOPE__ #lock:checked + .lock-label {
  background-color: rgb(167, 71, 245);
}
.__UIV_SCOPE__ .lock-label:active {
  transform: scale(0.9);
}
